        highlightedIndex: state.highlightedIndex,
      }
    : changes;

/**
 * NOTE: Error styling relies on the Label and InputContainer being direct siblings within the
 * DropdownContainer. Wrapping either element in an extra container (e.g., a <div>) will
 * break the sibling CSS selector and prevent error styles from being applied.
 *
 * Forcing error styles with utility classes like `v-input-error` on a
 * parent will cause non-listbox text content (e.g., a <span>subtitle</span> inside a
 * ListboxItem) to also turn red, which may not be the desired behavior.
 *
 * Keep the Label and InputContainer as direct children of DropdownContainer to ensure
 * error states render correctly.
 */
export const ErrorCombobox = () => {
  const id = useId();
  const [errorState, setErrorState] = useState(false);

  const {
    getInputProps,
    getItemProps,
    getLabelProps,
    getMenuProps,
    getToggleButtonProps,
    selectItem,
    highlightedIndex,
    inputValue,
    isOpen,
    selectedItem,
  } = useCombobox({
    id,
    items,
    itemToString,
    stateReducer,
  });
  const { id: listboxId, ...listboxProps } = getMenuProps();

  return (
    <Utility vFlexCol vGap={12}>
      <Combobox>
        <DropdownContainer className="v-flex v-flex-col v-gap-4">
          <Label {...getLabelProps()}>Label (required)</Label>
          <InputContainer className="v-flex-row">
            <Input
              aria-describedby="input-error-message"
              aria-haspopup="listbox"
              aria-invalid={errorState ? 'true' : 'false'}
              name="text-input-field-6"
              type="text"
              {...getInputProps({
                'aria-expanded': isOpen && items.length > 0,
                'aria-owns': listboxId,
                onChange: () => selectItem(null),
              })}
            />
            <Button
              aria-label="expand"
              buttonSize="small"
              colorScheme="tertiary"
              iconButton
              {...getToggleButtonProps()}
            >
              {isOpen ? <VisaChevronUpTiny /> : <VisaChevronDownTiny />}
            </Button>
          </InputContainer>
          {errorState && !isOpen && (
            <InputMessage aria-atomic="true" aria-live="assertive" id="input-error-message" role="alert">
              <VisaErrorTiny />
              This is required text that describes the error in more detail.
            </InputMessage>
          )}
        </DropdownContainer>
        <ListboxContainer>
          <Listbox id={listboxId} {...listboxProps}>
            {items.map((item, index) => (
              <ListboxItem
                className={highlightedIndex === index ? 'v-listbox-item-highlighted' : ''}
                key={`error-combobox-${index}`}
                {...getItemProps({
                  'aria-selected': inputValue === item.value,
                  index,
                  item,
                })}
              >
                <UtilityFragment vFlexShrink0>
                  <Radio tag="span" />
                </UtilityFragment>
                {item.value}
              </ListboxItem>
            ))}
          </Listbox>
        </ListboxContainer>
      </Combobox>
      <Utility vFlex vGap={12}>
        <Button onClick={() => (!inputValue && !selectedItem ? setErrorState(true) : setErrorState(false))}>
          Submit
        </Button>
        <Button
          colorScheme="secondary"
          onClick={() => {
            setErrorState(false);
            selectItem(null);
          }}
        >
          Reset
        </Button>
      </Utility>
    </Utility>
  );
};

