  const [items, setItems] = useState(defaultItems);
  const {
    getInputProps,
    getItemProps,
    getLabelProps,
    getMenuProps,
    getToggleButtonProps,
    highlightedIndex,
    inputValue,
    isOpen,
  } = useCombobox({
    id,
    items,
    itemToString,
    onInputValueChange: ({ inputValue }) => {
      setItems(defaultItems.filter(item => filter(item, inputValue)));
    },
    stateReducer,
  });

  const { id: listboxId, ...listboxProps } = getMenuProps();
  const resultsFound = items.length > 0;

  return (
    <Combobox>
      <UtilityFragment vFlex vFlexCol vGap={4}>
        <DropdownContainer>
          <Label {...getLabelProps()}>Label</Label>
          <UtilityFragment vFlexRow>
            <InputContainer>
              <Input
                aria-haspopup="listbox"
                name="text-input-field-12"
                type="text"
                {...getInputProps({
                  'aria-expanded': isOpen,
                  'aria-owns': listboxId,
                })}
              />
              <Button
                aria-label="expand"
                buttonSize="small"
                colorScheme="tertiary"
                iconButton
                {...getToggleButtonProps()}
              >
                {isOpen ? <VisaChevronUpTiny /> : <VisaChevronDownTiny />}
              </Button>
            </InputContainer>
          </UtilityFragment>
        </DropdownContainer>
      </UtilityFragment>
      <ListboxContainer>
        <Listbox id={listboxId} {...listboxProps}>
          {items.map((item, index) => (
            <ListboxItem
              className={highlightedIndex === index ? 'v-listbox-item-highlighted' : ''}
              key={`manual-autocomplete-combobox-${index}`}
              {...getItemProps({
                'aria-selected': inputValue === item.value,
                index,
                item,
              })}
            >
              <UtilityFragment vFlexShrink0>
                <Radio tag="span" />
              </UtilityFragment>
              {item.value}
            </ListboxItem>
          ))}
          {!resultsFound && (
            <UtilityFragment vFlex vJustifyContent="center" vPaddingVertical={8}>
              <li>No results found.</li>
            </UtilityFragment>
          )}
        </Listbox>
      </ListboxContainer>
    </Combobox>
  );
};

import { VisaChevronDownTiny, VisaChevronUpTiny } from '@visa/nova-icons-react';
import {
  Button,
  Combobox,
  DropdownContainer,
  Input,
  InputContainer,
  Label,
  Listbox,
  ListboxContainer,
  ListboxItem,
  Radio,
  UtilityFragment,
} from '@visa/nova-react';
import { useCombobox, type UseComboboxState, type UseComboboxStateChangeOptions } from 'downshift';
import { useId, useState } from 'react';

type Item = { value: string };

const defaultItems: Item[] = [
  { value: 'Option A' },
  { value: 'Option B' },
  { value: 'Option C' },
  { value: 'Option D' },
  { value: 'Option E' },
];

export const filter = (item: Item, inputValue: string = '') =>
  item.value.toLowerCase().includes(inputValue.toLowerCase());

export const itemToString = (item: Item | null) => (item ? item.value : '');

export const stateReducer = <TItemType,>(
  state: UseComboboxState<TItemType>,
  { type, changes }: UseComboboxStateChangeOptions<TItemType>
) =>
  // this prevents on mouse hover, the item in the list is automatic selected
  type === useCombobox.stateChangeTypes.ItemMouseMove || type === useCombobox.stateChangeTypes.MenuMouseLeave
    ? {
        ...changes, // default Downshift new state changes on item selection.
        highlightedIndex: state.highlightedIndex,
      }
    : changes;

export const AutocompleteWithAutomaticSelectionCombobox = () => {
  const id = useId();
  const [items, setItems] = useState(defaultItems);
  const {
    isOpen,
    getToggleButtonProps,
    getLabelProps,
    getInputProps,
    getMenuProps,
    getItemProps,
    setHighlightedIndex,
  } = useCombobox({
    id,
    items: items,
    itemToString,
    onInputValueChange: ({ inputValue }) => {
      setItems(defaultItems.filter(item => filter(item, inputValue)));
      if (inputValue) setHighlightedIndex(0);
    },
    stateReducer,
  });

  const { id: listboxId, ...listboxProps } = getMenuProps();

  return (
    <Combobox>
      <UtilityFragment vFlex vFlexCol vGap={4}>
        <DropdownContainer>
          <Label {...getLabelProps()}>Label</Label>
          <UtilityFragment vFlexRow>
            <InputContainer>
              <Input
                aria-haspopup="listbox"
                name="text-input-field-11"
                type="text"
                {...getInputProps({
                  'aria-autocomplete': 'list' as const,
                  'aria-expanded': isOpen,
                  'aria-owns': listboxId,
                })}
              />
              <Button
                aria-label="expand"
                buttonSize="small"
                colorScheme="tertiary"
                iconButton
                {...getToggleButtonProps()}
              >
                {isOpen ? <VisaChevronUpTiny /> : <VisaChevronDownTiny />}
              </Button>
            </InputContainer>
          </UtilityFragment>
        </DropdownContainer>
      </UtilityFragment>
      <ListboxContainer>
        <Listbox id={listboxId} {...listboxProps}>
          {items.length > 0 ? (
            items.map((item, index) => (
              <ListboxItem
                key={`auto-autocomplete-combobox-${index}`}
                {...getItemProps({
                  index,
                  item,
                })}
              >
                <UtilityFragment vFlexShrink0>
                  <Radio tag="span" />
                </UtilityFragment>
                {item.value}
              </ListboxItem>
            ))
          ) : (
            <UtilityFragment vFlex vJustifyContent="center" vPaddingVertical={8}>
              <li>No results found.</li>
            </UtilityFragment>
          )}
        </Listbox>
      </ListboxContainer>
    </Combobox>
  );
};

import {
  VisaChevronDownTiny,
  VisaChevronUpTiny,
  VisaClearAltTiny,
  VisaErrorTiny,
  VisaSearchLow,
} from '@visa/nova-icons-react';
import {
  Button,
  Combobox,
  DropdownContainer,
  Input,
  InputContainer,
  InputMessage,
  Label,
  Listbox,
  ListboxContainer,
  ListboxItem,
  Radio,
  Typography,
  Utility,
  UtilityFragment,
} from '@visa/nova-react';
import { type UseComboboxState, type UseComboboxStateChangeOptions, useCombobox } from 'downshift';
import { type FocusEvent, type ReactNode, useId, useMemo, useState } from 'react';
import { NovaAccordion } from '../accordion/reusable';
import { NovaCheckbox } from '../checkbox/reusable';
import { NovaInput } from '../input/reusable';

// Types
export interface ComboboxOption<T = string> {
  disabled?: boolean;
  label: string;
  value: T;
}

// Nova Combobox Component Props
export interface NovaComboboxProps<T = string> {
  autoSelect?: boolean;
  clearable?: boolean;
  description?: string;
  disabled?: boolean;
  filterable?: boolean;
  hideToggleButton?: boolean;
  id?: string;
  invalid?: boolean;
  label?: string;
  leadingIcon?: ReactNode;
  message?: string;
  onChange?: (value: T | null) => void;
  options?: ComboboxOption<T>[];
  readonly?: boolean;
  required?: boolean;
  value?: T | null;
}

// Item to string converter
const itemToString = <T,>(item: ComboboxOption<T> | null) => (item ? item.label : '');

// State reducer to prevent mouse hover selection
const stateReducer = <ItemType,>(
  state: UseComboboxState<ItemType>,
  { type, changes }: UseComboboxStateChangeOptions<ItemType>
) =>
  type === useCombobox.stateChangeTypes.ItemMouseMove || type === useCombobox.stateChangeTypes.MenuMouseLeave
    ? {
        ...changes,
        highlightedIndex: state.highlightedIndex,
      }
    : changes;

// Main Nova Combobox Component
export const NovaCombobox = <T = string,>({
  autoSelect = false,
  clearable = false,
  description,
  disabled = false,
  filterable = false,
  hideToggleButton = false,
  id: idProp,
  invalid = false,
  label = '',
  leadingIcon,
  message,
  onChange,
  options = [],
  readonly = false,
  required = false,
  value: valueProp,
  ...remainingProps
}: NovaComboboxProps<T>) => {
  const generatedId = useId();
  const id = idProp ?? generatedId;

  const [focused, setFocused] = useState(false);
  const [items, setItems] = useState(options);

  // Find initial item from value prop
  const initialItem = useMemo(
    () => (valueProp !== null && valueProp !== undefined ? options.find(opt => opt.value === valueProp) || null : null),
    [valueProp, options]
  );

  const {
    getInputProps,
    getItemProps,
    getLabelProps,
    getMenuProps,
    getToggleButtonProps,
    highlightedIndex,
    inputValue,
    isOpen,
    selectItem,
    selectedItem,
    setHighlightedIndex,
  } = useCombobox({
    id: `${id}-combobox`,
    items,
    itemToString,
    ...(initialItem && { initialSelectedItem: initialItem }),
    stateReducer,
    isItemDisabled: item => item.disabled || false,
    onInputValueChange: ({ inputValue: newInputValue }) => {
      if (filterable && newInputValue !== undefined) {
        const filtered = options.filter(item => item.label.toLowerCase().includes(newInputValue.toLowerCase()));
        setItems(filtered);
        if (autoSelect && newInputValue) {
          setHighlightedIndex(0);
        }
      }
    },
    onSelectedItemChange: ({ selectedItem: newSelectedItem }) => {
      onChange?.(newSelectedItem?.value ?? null);
    },
  });

  const { id: listboxId, ...listboxProps } = getMenuProps();

  const handleBlur = (event: FocusEvent<HTMLDivElement>) => {
    if (!event.currentTarget.contains(event.relatedTarget)) {
      setFocused(false);
    }
  };

  const onClear = () => {
    selectItem(null);
    onChange?.(null);
  };

  const showClearButton = clearable && inputValue.length > 0 && focused && !readonly && !disabled;
  const resultsFound = items.length > 0;
  const showInlineMessage = description && !isOpen && !invalid;
  const showErrorMessage = invalid && message && !isOpen;

  // Calculate aria-describedby
  const inputDescribedBy = useMemo(() => {
    const ids: string[] = [];
    if (description) ids.push(`${id}-description`);
    if (message) ids.push(`${id}-message`);
    return ids.length > 0 ? ids.join(' ') : undefined;
  }, [id, description, message]);

  return (
    <Combobox>
      <UtilityFragment vFlex vFlexCol vGap={4}>
        <DropdownContainer>
          <Label {...getLabelProps()}>
            {label}
            {required ? ' (required)' : ''}
          </Label>
          <UtilityFragment vFlexRow>
            <InputContainer
              onBlur={handleBlur}
              onFocus={() => {
                setFocused(true);
              }}
            >
              {leadingIcon}
              <Input
                aria-describedby={inputDescribedBy}
                aria-haspopup="listbox"
                aria-invalid={invalid}
                disabled={disabled}
                name={`${id}-input`}
                type="text"
                {...getInputProps({
                  'aria-expanded': isOpen,
                  'aria-owns': listboxId,
                  ...(filterable && { 'aria-autocomplete': 'list' as const }),
                  ...(readonly && { readOnly: true }),
                })}
                {...remainingProps}
              />
              {showClearButton && (
                <Button
                  aria-label="clear"
                  buttonSize="small"
                  colorScheme="tertiary"
                  iconButton
                  onClick={onClear}
                  subtle
                >
                  <VisaClearAltTiny />
                </Button>
              )}
              {!hideToggleButton && (
                <Button
                  aria-label="expand"
                  buttonSize="small"
                  colorScheme="tertiary"
                  iconButton
                  disabled={readonly || disabled}
                  {...getToggleButtonProps()}
                >
                  {isOpen ? <VisaChevronUpTiny /> : <VisaChevronDownTiny />}
                </Button>
              )}
            </InputContainer>
          </UtilityFragment>
          {showInlineMessage && <InputMessage id={`${id}-description`}>{description}</InputMessage>}
          {showErrorMessage && (
            <InputMessage aria-atomic="true" aria-live="assertive" id={`${id}-message`} role="alert">
              <VisaErrorTiny />
              {message}
            </InputMessage>
          )}
        </DropdownContainer>
      </UtilityFragment>
      <ListboxContainer>
        <Listbox id={listboxId} {...listboxProps}>
          {resultsFound ? (
            items.map((item, index) => (
              <ListboxItem
                key={`${id}-item-${index}`}
                className={highlightedIndex === index ? 'v-listbox-item-highlighted' : ''}
                {...getItemProps({
                  index,
                  item,
                  'aria-selected': selectedItem?.value === item.value,
                  'aria-disabled': item.disabled,
                })}
              >
                <UtilityFragment vFlexShrink0>
                  <Radio tag="span" />
                </UtilityFragment>
                {item.label}
              </ListboxItem>
            ))
          ) : (
            <UtilityFragment vFlex vJustifyContent="center" vPaddingVertical={8}>
              <li>
                <Typography variant="label-large">No results found.</Typography>
              </li>
            </UtilityFragment>
          )}
        </Listbox>
      </ListboxContainer>
    </Combobox>
  );
};

