import { VisaErrorTiny } from '@visa/nova-icons-react';
import { Button, Input, InputContainer, InputMessage, Label, Utility } from '@visa/nova-react';
import { useState, type FormEvent } from 'react';

// TIP: Customize this ID, pass it as a prop, or auto-generate it with useId() from @react
const id = 'cvv-input';

const cvvLength = 3;

export const CVVInput = () => {
  const [invalid, setInvalid] = useState(false);
  const [focused, setFocused] = useState(false);

  const onReset = () => {
    setInvalid(false);
  };
  const onSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const isValid = event.currentTarget.checkValidity();
    const formData = new FormData(event.currentTarget);
    const formDataObject = Object.fromEntries(formData.entries());

    // If valid, alert with CVV
    if (isValid) alert(`Success!\nCVV: ${formDataObject['cvv-input']}`);
    // If invalid, focus on invalid element
    else (event.currentTarget.querySelector(':invalid') as HTMLInputElement)?.focus();

    setInvalid(!isValid);
  };

  return (
    <Utility<'form'> noValidate onReset={onReset} onSubmit={onSubmit} tag="form" vFlex vFlexCol vGap={4}>
      <Label htmlFor={id}>Security code</Label>
      <InputContainer>
        <Input
          aria-describedby={`${id}-message`}
          aria-invalid={invalid}
          aria-required="true"
          autoComplete="cc-csc"
          id={id}
          maxLength={cvvLength}
          name={id}
          onBlur={() => setFocused(false)}
          onFocus={() => setFocused(true)}
          pattern={`[0-9]{${cvvLength}}`}
          required
          type={focused ? 'text' : 'password'}
        />
      </InputContainer>
      {invalid && (
        <InputMessage id={`${id}-message`}>
          <VisaErrorTiny />
          Please choose a valid security code.
        </InputMessage>
      )}
      <Utility vFlex vFlexRow vGap={8} vMarginTop={16}>
        <Button type="submit">Submit</Button>
        <Button colorScheme="secondary" type="reset">
          Reset
        </Button>
      </Utility>
    </Utility>
  );
};

import {
  VisaAccountLow,
  VisaCheckmarkLow,
  VisaClearAltTiny,
  VisaErrorTiny,
  VisaPasswordHideTiny,
  VisaPasswordShowTiny,
} from '@visa/nova-icons-react';
import {
  Button,
  Checkbox,
  Input,
  InputContainer,
  InputMessage,
  type InputProperties,
  Label,
  Textarea,
  type TextAreaProperties,
  Typography,
  Utility,
} from '@visa/nova-react';
import {
  type ChangeEvent,
  type ComponentPropsWithRef,
  type ElementType,
  type FocusEvent,
  type ReactNode,
  useId,
  useMemo,
  useRef,
  useState,
} from 'react';
import { NovaAccordion } from '../accordion/reusable';

type InheritedProps<ET extends ElementType> = ET extends 'input'
  ? InputProperties<'input'>
  : ET extends 'textarea'
    ? TextAreaProperties<'textarea'>
    : ComponentPropsWithRef<ET>;

// Nova Input Component Props
export type NovaInputProps<ET extends ElementType = 'input'> = InheritedProps<ET> & {
  blockSize?: string;
  clearable?: boolean;
  inline?: boolean;
  invalid?: boolean;
  label?: string;
  maskable?: boolean;
  message?: string;
  otp?: boolean;
  prefix?: string;
  prefixIcon?: ReactNode;
  readonly?: boolean;
  required?: boolean;
  resizable?: boolean;
  step?: number;
  suffix?: string;
  suffixIcon?: ReactNode;
  textarea?: boolean;
};

// Main Nova Input Component
export const NovaInput = <ET extends ElementType = 'input'>({
  blockSize = 'var(--v-input-container-block-size)',
  clearable = false,
  disabled = false,
  id: idProp,
  inline = false,
  invalid = false,
  label = '',
  maskable = false,
  message,
  otp = false,
  placeholder,
  prefix,
  prefixIcon,
  readonly = false,
  required = false,
  resizable = true,
  step,
  suffix,
  suffixIcon,
  textarea = false,
  type: typeProp,
  value: controlledValue,
  onChange,
  ...remainingInputProps
}: NovaInputProps<ET>) => {
  const generatedId = useId();
  const id = idProp ?? generatedId;

  const [internalValue, setInternalValue] = useState('');
  const [inFocus, setInFocus] = useState(false);
  const [masked, setMasked] = useState(true);

  const inputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  // Use controlled value if provided, otherwise use internal state
  const value = controlledValue !== undefined ? controlledValue : internalValue;

  // Determine the input type
  const inputType = useMemo(() => {
    if (typeProp) return typeProp;
    if (!maskable) return 'text';
    return masked ? 'password' : 'text';
  }, [typeProp, maskable, masked]);

  // Calculate aria-describedby
  const inputDescribedBy = useMemo(() => {
    const ids: string[] = [];
    if (message) ids.push(`${id}-message`);
    if (prefix) ids.push(`${id}-prefix`);
    if (suffix) ids.push(`${id}-suffix`);
    return ids.length > 0 ? ids.join(' ') : undefined;
  }, [message, prefix, suffix, id]);

  const handleInputChange = (event: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const newValue = event.target.value;
    if (controlledValue === undefined) {
      setInternalValue(newValue);
    }
    onChange?.(event as ChangeEvent<HTMLInputElement>);
  };

  const handleBlur = (event: FocusEvent<HTMLDivElement>) => {
    const relatedTarget = event.relatedTarget as HTMLElement;
    if (
      relatedTarget !== buttonRef.current &&
      relatedTarget !== inputRef.current &&
      relatedTarget !== textareaRef.current &&
      !event.currentTarget.contains(relatedTarget)
    ) {
      setInFocus(false);
    }
  };

  const handleClear = () => {
    handleInputChange({ target: { value: '' } } as ChangeEvent<HTMLInputElement | HTMLTextAreaElement>);
    if (textarea) {
      textareaRef.current?.focus();
    } else {
      inputRef.current?.focus();
    }
  };

  const handleToggleMask = () => {
    setMasked(prev => !prev);
  };

  const showClearButton = value && value.length > 0 && inFocus && clearable;

  return (
    <Utility
      vAlignItems={inline ? 'start' : undefined}
      vFlex
      vFlexCol={!inline}
      vFlexRow={inline}
      vFlexWrap={inline}
      vGap={4}
    >
      <Label htmlFor={`${id}-input`} style={inline ? { lineHeight: 'var(--v-input-container-block-size)' } : undefined}>
        {label} {required ? ' (required)' : ''}
      </Label>
      <Utility vFlex vFlexCol vFlexGrow vGap={4}>
        <InputContainer
          onBlur={handleBlur}
          onFocus={() => setInFocus(true)}
          style={otp ? { inlineSize: '160px' } : undefined}
        >
          {prefixIcon}
          {prefix && (
            <Typography className="v-typography-body-2-bold" id={`${id}-prefix`} tag="span">
              {prefix}
            </Typography>
          )}

          {textarea ? (
            <Textarea
              ref={textareaRef}
              aria-describedby={inputDescribedBy}
              aria-invalid={invalid}
              disabled={disabled}
              fixed={!resizable}
              id={`${id}-input`}
              onChange={handleInputChange}
              placeholder={placeholder}
              readOnly={readonly}
              required={required}
              style={{ blockSize }}
              value={value}
              {...remainingInputProps}
            />
          ) : (
            <Input
              ref={inputRef}
              aria-describedby={inputDescribedBy}
              aria-invalid={invalid}
              disabled={disabled}
              id={`${id}-input`}
              onChange={handleInputChange}
              otp={otp}
              placeholder={placeholder}
              readOnly={readonly}
              required={required}
              step={step}
              type={inputType}
              value={value}
              {...remainingInputProps}
            />
          )}

          {showClearButton && (
            <Button
              aria-label="clear"
              ref={buttonRef}
              buttonSize="small"
              colorScheme="tertiary"
              disabled={disabled}
              iconButton
              onClick={handleClear}
              subtle
            >
              <VisaClearAltTiny />
            </Button>
          )}

          {suffix && (
            <Typography className="v-typography-body-2-bold" id={`${id}-suffix`} tag="span">
              {suffix}
            </Typography>
          )}

          {maskable && (
            <Button
              aria-label={masked ? 'show password' : 'hide password'}
              buttonSize="small"
              colorScheme="tertiary"
              disabled={disabled}
              iconButton
              onClick={handleToggleMask}
            >
              {masked ? <VisaPasswordShowTiny /> : <VisaPasswordHideTiny />}
            </Button>
          )}

          {suffixIcon}
        </InputContainer>

        {message && (
          <InputMessage aria-atomic={invalid} aria-live={invalid ? 'assertive' : undefined} id={`${id}-message`}>
            {invalid && <VisaErrorTiny />}
            {message}
          </InputMessage>
        )}
      </Utility>
    </Utility>
  );
};

