                        removeSelectedItem(item);
                      } else {
                        setSelectedItems([...selectedItems, item]);
                        setInputValue('');
                        setHasError(false);
                      }
                    },
                  })}
                >
                  <Checkbox tag="span" />
                  {item.value}
                </ListboxItem>
              ))}
            </Listbox>
          </UtilityFragment>
        </ListboxContainer>
