import { VisaChevronLeftTiny, VisaChevronRightTiny } from '@visa/nova-icons-react';
import { Button, Pagination, usePagination } from '@visa/nova-react';

export const SlimPagination = () => {
  const { pages, selectedPage, isFirstPage, isLastPage, onPageChange, onPreviousPage, onNextPage } = usePagination({
    totalPages: 10,
    compact: true,
    blockMaxLength: 5,
  });

  return (
    <nav aria-label="pagination">
      <Pagination className="v-align-items-center v-gap-4">
        <li>
          <Button
            aria-label="Go to previous page"
            buttonSize="small"
            colorScheme="tertiary"
            disabled={isFirstPage}
            iconButton
            onClick={onPreviousPage}
          >
            <VisaChevronLeftTiny rtl />
          </Button>
        </li>
        {pages.map(page => (
          <li key={page} className="v-mobile-container-hide">
            <Button
              aria-current={page === selectedPage ? 'true' : undefined}
              aria-label={`Page ${page}`}
              colorScheme="tertiary"
              onClick={() => onPageChange(+page)}
            >
              {page}
            </Button>
          </li>
        ))}
        <li>
          <Button
            aria-label="Go to next page"
            buttonSize="small"
            colorScheme="tertiary"
            disabled={isLastPage}
            iconButton
            onClick={onNextPage}
          >
            <VisaChevronRightTiny rtl />
          </Button>
        </li>
      </Pagination>
    </nav>
  );
};

import {
  VisaArrowEndTiny,
  VisaArrowStartTiny,
  VisaChevronDownTiny,
  VisaChevronLeftTiny,
  VisaChevronRightTiny,
  VisaOptionHorizontalTiny,
} from '@visa/nova-icons-react';
import {
  Button,
  calculatePagesFromTo,
  calculateTotalPages,
  InputContainer,
  InputControl,
  InputMessage,
  Label,
  Pagination,
  PaginationOverflow,
  Select,
  usePagination,
  Utility,
  UtilityFragment,
} from '@visa/nova-react';
import { type CSSProperties, type FormEvent, useEffect, useId, useState } from 'react';
import { NovaAccordion } from '../accordion/reusable';
import { NovaCheckbox } from '../checkbox/reusable';
import { NovaInput } from '../input/reusable';

// Nova Pagination Component Props
export interface NovaPaginationProps {
  'aria-label'?: string;
  blockMaxLength?: number;
  compact?: boolean;
  disabled?: boolean;
  id?: string;
  inline?: boolean;
  itemsPerPage?: number;
  itemsPerPageOptions?: number[];
  onItemsPerPageChange?: (itemsPerPage: number) => void;
  onPageChange?: (page: number) => void;
  page?: number;
  selectLabel?: string;
  showItemsPerPage?: boolean;
  showPageRange?: boolean;
  totalItems?: number;
}

// Main Nova Pagination Component
export const NovaPagination = ({
  'aria-label': ariaLabel = 'Pagination for table',
  blockMaxLength,
  compact = false,
  disabled = false,
  id: idProp,
  inline = true,
  itemsPerPage: itemsPerPageProp = 10,
  itemsPerPageOptions = [5, 10, 15, 20],
  onItemsPerPageChange: onItemsPerPageChangeProp,
  onPageChange: onPageChangeProp,
  page,
  selectLabel = 'Results per page',
  showItemsPerPage = true,
  showPageRange = true,
  totalItems = 1,
  ...remainingProps
}: NovaPaginationProps) => {
  const generatedId = useId();
  const id = idProp ?? generatedId;
  const [itemsPerPageControlled, setItemsPerPageControlled] = useState(10);

  const itemsPerPage = itemsPerPageProp ?? itemsPerPageControlled;
  const setItemsPerPage = onItemsPerPageChangeProp ?? setItemsPerPageControlled;

  const totalPages = calculateTotalPages(totalItems, itemsPerPage);
  const {
    isFirstPage,
    isLastPage,
    onFirstPage,
    onLastPage,
    onNextPage,
    onPageChange,
    onPreviousPage,
    pages,
    selectedPage,
  } = usePagination({
    blockMaxLength,
    compact,
    setSelectedPage: onPageChangeProp,
    selectedPage: page,
    totalPages,
  });

  const { from, to } = calculatePagesFromTo(totalItems, itemsPerPage, selectedPage);

  const onItemsPerPageChange = (event: FormEvent<HTMLSelectElement>) => {
    onFirstPage();
    setItemsPerPage(+event.currentTarget.value);
  };

  useEffect(() => {
    onFirstPage();
  }, [itemsPerPage, totalItems]);

  return (
    <Utility
      vAlignItems="center"
      vFlex
      vFlexRow
      vFlexWrapReverse
      vGap={10}
      vJustifyContent="between"
      {...remainingProps}
    >
      {(showItemsPerPage || showPageRange) && (
        <Utility
          style={{ textWrap: 'nowrap' } as CSSProperties}
          tag="fieldset"
          vAlignItems={inline ? 'center' : undefined}
          vFlex
          vFlexRow={inline}
          vFlexCol={!inline}
          vGap={8}
          vFlexWrap
        >
          {showItemsPerPage && (
            <>
              <UtilityFragment vFlexShrink0>
                <Label htmlFor={`${id}-select`} variant="label-large">
                  {selectLabel}
                </Label>
              </UtilityFragment>
              <InputContainer style={{ flexBasis: inline ? 'max-content' : undefined }}>
                <Select
                  aria-describedby={showPageRange ? `${id}-select-message` : undefined}
                  disabled={disabled}
                  id={`${id}-select`}
                  name={`${id}-select`}
                  onChange={onItemsPerPageChange}
                  value={itemsPerPage}
                >
                  {itemsPerPageOptions.map(option => (
                    <option key={`${id}-items-per-page-option-${option}`} value={option}>
                      {option}
                    </option>
                  ))}
                </Select>
                <InputControl>
                  <VisaChevronDownTiny />
                </InputControl>
              </InputContainer>
            </>
          )}
          {showPageRange && (
            <InputMessage
              id={`${id}-select-message`}
              variant="body-2"
            >{`${from} - ${to} of ${totalItems}`}</InputMessage>
          )}
        </Utility>
      )}
      <UtilityFragment>
        <nav aria-label={ariaLabel} role="navigation">
          <UtilityFragment vAlignItems="center" vGap={4} vFlex vFlexWrap>
            <Pagination>
              {!compact && (
                <li>
                  <Button
                    aria-label="Go to first page"
                    buttonSize="small"
                    colorScheme="tertiary"
                    disabled={isFirstPage || disabled}
                    iconButton
                    onClick={onFirstPage}
                  >
                    <VisaArrowStartTiny rtl />
                  </Button>
                </li>
              )}
              <li>
                <Button
                  aria-label="Go to previous page"
                  buttonSize="small"
                  colorScheme="tertiary"
                  disabled={isFirstPage || disabled}
                  iconButton
                  onClick={onPreviousPage}
                >
                  <VisaChevronLeftTiny rtl />
                </Button>
              </li>
              {pages.map((pageNumber, index) =>
                pageNumber === -1 ? (
                  <UtilityFragment key={`table-pagination-ellipse-${index}`} vAlignItems="center" vFlex>
                    <PaginationOverflow>
                      <VisaOptionHorizontalTiny />
                    </PaginationOverflow>
                  </UtilityFragment>
                ) : (
                  <li key={`table-pagination-page-${pageNumber}`}>
                    <Button
                      aria-current={selectedPage === pageNumber}
                      aria-label={`Page ${pageNumber}`}
                      colorScheme="tertiary"
                      disabled={disabled}
                      onClick={() => onPageChange(pageNumber as number)}
                    >
                      {pageNumber}
                    </Button>
                  </li>
                )
              )}
              <li>
                <Button
                  aria-label="Go to next page"
                  buttonSize="small"
                  colorScheme="tertiary"
                  disabled={isLastPage || disabled}
                  iconButton
                  onClick={onNextPage}
                >
                  <VisaChevronRightTiny rtl />
                </Button>
              </li>
              {!compact && (
                <li>
                  <Button
                    aria-label="Go to last page"
                    buttonSize="small"
                    colorScheme="tertiary"
                    disabled={isLastPage || disabled}
                    iconButton
                    onClick={onLastPage}
                  >
                    <VisaArrowEndTiny rtl />
                  </Button>
                </li>
              )}
            </Pagination>
          </UtilityFragment>
        </nav>
      </UtilityFragment>
    </Utility>
  );
};

