import { VisaErrorTiny } from '@visa/nova-icons-react';
import { Utility, RadioPanel, Radio, Label, InputMessage, Button, Typography } from '@visa/nova-react';
import { useRef, useState, type ChangeEvent } from 'react';

// TIP: Customize this ID, pass it as a prop, or auto-generate it with useId() from @react
const id = 'error-group-panel-radio';

const radios = ['Label 1', 'Label 2', 'Label 3'];

export const ErrorPanelGroupRadio = () => {
  const ref = useRef<HTMLInputElement>(null);
  const [errorState, setErrorState] = useState(false);
  const [option, setOption] = useState('');

  const handleChangeState = (e: ChangeEvent<HTMLInputElement>) => {
    setOption(e.target.value);
  };
  const handleOnSubmit = () => {
    if (option !== '') {
      setErrorState(false);
    } else {
      setOption('');
      setErrorState(true);
    }
    ref?.current?.focus();
  };
  return (
    <>
      <fieldset aria-labelledby={`${id}-legend ${id}-message`}>
        <Typography id={`${id}-legend`} tag="legend" variant="label">
          Group label (required)
        </Typography>
        <Utility vFlex vFlexCol vGap={8}>
          {radios.map((radio, index) => (
            <RadioPanel className="v-align-items-start" htmlFor={`${id}-option-${index}`} key={`${id}-option-${index}`}>
              <Utility vFlex vGap={2} style={{ inlineSize: '100%' }}>
                <Radio
                  aria-describedby={`${id}-option-${index}-message`}
                  aria-invalid={errorState}
                  checked={option === `${index}`}
                  className="v-flex-shrink-0"
                  id={`${id}-option-${index}`}
                  name={`${id}-options`}
                  onChange={handleChangeState}
                  ref={index === 0 ? ref : undefined}
                  value={index}
                />
                <Utility vFlex vFlexCol vGap={2} vMarginVertical={8}>
                  <Label htmlFor={`${id}-option-${index}`}>{radio}</Label>
                  <InputMessage id={`${id}-option-${index}-message`}>
                    This is optional text that describes the label in more detail.
                  </InputMessage>
                </Utility>
              </Utility>
            </RadioPanel>
          ))}
        </Utility>
        {errorState && (
          <InputMessage
            aria-atomic="true"
            aria-live="assertive"
            className="v-typography-label v-flex v-align-items-center"
            id={`${id}-message`}
            role="alert"
          >
            <VisaErrorTiny />
            This is required text that describes the error in more detail.
          </InputMessage>
        )}
      </fieldset>
      <Utility vFlex vFlexRow vPaddingTop={12} vGap={12}>
        <Button onClick={handleOnSubmit}>Submit</Button>
        <Button colorScheme="secondary" onClick={() => setOption('')}>
          Reset
        </Button>
      </Utility>
    </>
  );
};

import { VisaErrorTiny } from '@visa/nova-icons-react';
import {
  Button,
  InputContainer,
  InputMessage,
  Label,
  Radio,
  RadioPanel,
  Utility,
  UtilityFragment,
} from '@visa/nova-react';
import type { RadioProperties } from '@visa/nova-react';
import { useId, useMemo, useRef, useState } from 'react';
import { NovaAccordion } from '../accordion/reusable';
import { NovaCheckbox } from '../checkbox/reusable';
import { NovaInput } from '../input/reusable';

// Nova Radio Component Props
export type NovaRadioProps = RadioProperties & {
  alignEnd?: boolean;
  checked?: boolean;
  description?: string;
  disabled?: boolean;
  id?: string;
  invalid?: boolean;
  label?: string;
  message?: string;
  name: string;
  panel?: boolean;
  required?: boolean;
  value: string | number;
};

// Main Nova Radio Component
export const NovaRadio = ({
  alignEnd = false,
  checked = false,
  description,
  disabled = false,
  id: idProp,
  invalid = false,
  label = '',
  message,
  name,
  onChange,
  panel = false,
  required = false,
  value,
  ...remainingInputProps
}: NovaRadioProps) => {
  const generatedId = useId();
  const id = idProp ?? generatedId;
  const radioInputRef = useRef<HTMLInputElement>(null);

  // Calculate aria-describedby
  const inputDescribedBy = useMemo(() => {
    const ids: string[] = [];
    if (message) ids.push(`${id}-message`);
    if (description) ids.push(`${id}-description`);
    return ids.length > 0 ? ids.join(' ') : undefined;
  }, [message, description, id]);

  // Handle click on panel
  const handlePanelClick = () => {
    if (!disabled && radioInputRef.current) {
      radioInputRef.current.click();
    }
  };

  const radioContent = (
    <UtilityFragment vAlignItems={panel && description ? 'start' : undefined} vFlex vFlexRowReverse={alignEnd}>
      <InputContainer>
        <Radio
          ref={radioInputRef}
          aria-describedby={inputDescribedBy}
          aria-required={required ? true : undefined}
          checked={checked}
          disabled={disabled}
          id={`${id}-input`}
          aria-invalid={invalid}
          name={name}
          onChange={onChange}
          required={required}
          type="radio"
          value={value}
          {...remainingInputProps}
        />
        <Utility vFlex vFlexCol vFlexGrow={alignEnd} vGap={2} vMarginVertical={8}>
          <Label htmlFor={`${id}-input`}>{label}</Label>
          {description && <InputMessage id={`${id}-description`}>{description}</InputMessage>}
        </Utility>
      </InputContainer>
    </UtilityFragment>
  );

  return (
    <>
      {panel ? <RadioPanel onClick={handlePanelClick}>{radioContent}</RadioPanel> : radioContent}

      <UtilityFragment vMarginTop={4}>
        <InputMessage
          aria-atomic={invalid ? true : undefined}
          aria-live={invalid ? 'assertive' : undefined}
          id={`${id}-message`}
        >
          {invalid && message && <VisaErrorTiny />}
          {message && message}
        </InputMessage>
      </UtilityFragment>
    </>
  );
};

