// Select Option Type
export interface NovaSelectOption {
  disabled?: boolean;
  hidden?: boolean;
  label: string;
  value: ComponentPropsWithoutRef<'option'>['value'];
}

// Nova Select Component Props
export interface NovaSelectProps extends ComponentPropsWithRef<'select'> {
  disabled?: boolean;
  id?: string;
  inline?: boolean;
  invalid?: boolean;
  label?: string;
  message?: string;
  options?: NovaSelectOption[];
  readonly?: boolean;
  required?: boolean;
}

// Main Nova Select Component
export const NovaSelect = ({
  disabled = false,
  id: idProp,
  inline = false,
  invalid = false,
  label = '',
  message,
  onChange,
  options = [],
  readonly = false,
  required = false,
  value,
  ...remainingSelectProps
}: NovaSelectProps) => {
  const generatedId = useId();
  const id = idProp ?? generatedId;

  return (
    <Utility vAlignItems={inline ? 'start' : undefined} vFlex vFlexCol={!inline} vFlexWrap vGap={4}>
      <Label
        htmlFor={`${id}-select`}
        id={`${id}-label`}
        style={
          inline
            ? {
                lineHeight: 'var(--v-input-container-block-size)',
                textWrap: 'nowrap',
              }
            : undefined
        }
      >
        {label} {required ? ' (required)' : ''}
      </Label>
      <Utility vFlex vFlexCol vFlexGrow vGap={4}>
        <InputContainer>
          <Select
            aria-describedby={`${id}-message`}
            aria-invalid={invalid}
            disabled={disabled || readonly}
            id={`${id}-select`}
            onChange={onChange}
            required={required}
            value={value}
            {...remainingSelectProps}
          >
            <option hidden></option>
            {options.map((option, i) => (
              <option
                key={`${id}-option-${option.value}-${i}`}
                disabled={readonly || disabled || option.disabled}
                hidden={option.hidden}
                value={option.value}
              >
                {option.label}
              </option>
            ))}
          </Select>
          <VisaChevronDownTiny />
        </InputContainer>
        <InputMessage
          aria-atomic={invalid ? true : undefined}
          aria-live={invalid ? 'assertive' : undefined}
          id={`${id}-message`}
        >
          {invalid && <VisaErrorTiny />}
          {message && message}
        </InputMessage>
      </Utility>
    </Utility>
  );
};
