  alignStart?: boolean;
  description?: string;
  disabled?: boolean;
  invalid?: boolean;
  label?: string;
  message?: string;
  required?: boolean;
};

// Main Nova Switch Component
export const NovaSwitch = ({
  alignStart = false,
  checked = false,
  description,
  disabled = false,
  id: idProp,
  invalid = false,
  label = '',
  message,
  onChange,
  required = false,
  ...remainingInputProps
}: NovaSwitchProps) => {
  const generatedId = useId();
  const id = idProp ?? generatedId;

  // Calculate aria-describedby
  const inputDescribedBy =
    message || description
      ? [message ? `${id}-message` : '', description ? `${id}-description` : ''].filter(Boolean).join(' ')
      : undefined;

  const switchInput = (
    <Switch
      aria-describedby={inputDescribedBy}
      aria-required={required ? true : undefined}
      checked={checked}
      disabled={disabled}
      id={`${id}-input`}
      aria-invalid={invalid}
      onChange={onChange}
      required={required}
      type="checkbox"
      {...remainingInputProps}
    />
  );

  return (
    <>
      <Utility
        vAlignItems="center"
        vFlex
        style={{ flexBasis: 'min-content' }}
        vFlexWrap
        vGap={10}
        vJustifyContent="between"
        vMargin={8}
      >
        {alignStart && switchInput}
        <Utility vFlex style={{ flexBasis: 'min-content' }} vFlexCol vFlexGrow vGap={2} vMarginTop={2}>
          <SwitchLabel className="v-typography-label-large" htmlFor={`${id}-input`}>
            {label}
            {required ? ' (required)' : ''}
          </SwitchLabel>
          {description && (
            <Typography variant="body-3" id={`${id}-description`} tag="span">
              {description}
            </Typography>
          )}
        </Utility>
        {!alignStart && switchInput}
      </Utility>

      <UtilityFragment vMarginTop={4}>
        <InputMessage
          aria-atomic={invalid ? true : undefined}
          aria-live={invalid ? 'assertive' : undefined}
          id={`${id}-message`}
        >
          {invalid && message && <VisaErrorTiny />}
          {message && message}
        </InputMessage>
      </UtilityFragment>
    </>
  );
};

