  const { getReferenceProps, getFloatingProps } = useInteractions([dismiss, focus, hover, role]);

  return (
    <Utility vFlex vJustifyContent="center" vMargin={24}>
      <Button ref={refs.setReference} {...getReferenceProps()}>
        Primary action
      </Button>
      {isOpen && (
        <Tooltip
          ref={refs.setFloating}
          style={{
            left: x,
            position: strategy,
            top: y,
            width: 'fit-content',
          }}
          {...getFloatingProps()}
        >
          This is a tooltip
        </Tooltip>
      )}
    </Utility>
  );
};

