snippets.patterns/application-layouts/styles-hori:
/* Layout structure with header on top and content below, filling full viewport */
.layout-horizontal {
  height: 100vh;
  z-index: 1;
  display: grid;
  grid-template-columns: 1fr;
  grid-template-rows: auto 1fr;
  grid-template-areas: 'header' 'content';
  background-color: var(--palette-default-surface-3, #f0f0f0);
}

/* Higher z-index keeps header above other elements when scrolling */
.layout-horizontal .layout-header {
  z-index: 3;
  position: relative;
  grid-area: header;
}

/* Allows content area to scroll independently while header stays fixed */
.layout-horizontal .layout-content {
  position: relative;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  grid-area: content;
}

/* Main content grows to fill available space, pushing footer to bottom */
.layout-horizontal main {
  display: block;
  flex-grow: 1;
}

.layout-horizontal header.v-nav {
  position: relative;
}

/* Match footer background to overall page background */
.layout-horizontal footer {
  --v-footer-background-color: var(--v-palette-default-surface-3);
}

/* Show/hide elements based on screen size for mobile and desktop views */
@container (max-width: 1003px) {
  .layout-horizontal .v-mobile-container-hide {
    display: none;
  }
  .layout-horizontal .v-desktop-container-hide {
    display: block;
  }
  .layout-horizontal .v-desktop-container-hide.v-hide {
    display: none;
  }
}
@container (min-width: 1004px) {
  .layout-horizontal .v-mobile-container-hide {
    display: flex;
  }
  .layout-horizontal .v-desktop-container-hide {
    display: none;
  }
}

