      >
        {/* Primary navigation tabs - dynamically generated, replace with your navigation */}
        <Tabs className="v-gap-8">
          {Array.from({ length: 3 }).map((_, index) => {
            return (
              <Tab key={`second-tier-item-${index}`}>
