snippets.patterns/application-layouts/styles-vert:
/* Layout with sidebar navigation on left and main content on right, both filling full height */
.layout-vertical {
    height: 100vh;
    display: grid;
    grid-template-columns: auto 1fr;
    grid-template-rows: 100%;
    grid-template-areas: "header content";
    background-color: var(--palette-default-surface-3, #f0f0f0);
}

/* When sidebar navigation is expanded, set fixed width for consistent spacing */
.layout-vertical:has(.v-nav .v-tabs) {
    grid-template-columns: 242px 1fr;
}

/* Higher z-index keeps sidebar navigation above other elements */
.layout-vertical .layout-header {
    z-index: 3;
    position: relative;
    grid-area: header;
}

/* Allows content area to scroll independently while sidebar stays fixed */
.layout-vertical .layout-content {
    position: relative;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    grid-area: content;
}

/* Main content grows to fill available space, pushing footer to bottom */
.layout-vertical main {
    display: block;
    flex-grow: 1;
}

/* Match footer background to overall page background */
.layout-vertical footer {
  --v-footer-background-color: var(--v-palette-default-surface-3);
}

