                  }
                  tag="sup"
                >
                  3
                </Badge>
              </Button>
            </Tab>
          </Tabs>
          <UtilityFragment vMarginTop={5}>
            <Divider dividerType="decorative" />
          </UtilityFragment>
          {/* Account section at bottom of mobile menu */}
          <UtilityFragment vMarginTop={6} className="v-tabs-vertical">
