snippets.patterns/application-layouts/styles-mixe:
/* Layout with header spanning full width, sidebar on left, and content on right */
.layout-mixed {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-rows: auto 1fr;
  grid-template-areas: 'header header' 'nav content';
  height: 100vh;
  background-color: var(--palette-default-surface-3, #f0f0f0);
}

/* When sidebar navigation is expanded, set fixed width for consistent spacing */
.layout-mixed:has(.mixed-vertical-tabs) {
  grid-template-columns: 242px 1fr !important;
}

/* Higher z-index keeps header above other elements when scrolling */
.layout-mixed .layout-header {
  z-index: 3;
  position: relative;
  grid-area: header;
}

.layout-mixed .layout-vertical-mixed {
  grid-area: nav;
}

/* Allows content area to scroll independently while header and sidebar stay fixed */
.layout-mixed .layout-content {
  position: relative;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  grid-area: content;
}

/* Main content grows to fill available space, pushing footer to bottom */
.layout-mixed main {
  display: block;
  flex-grow: 1;
}

/* Match footer background to overall page background */
.layout-mixed footer {
  --v-footer-background-color: var(--v-palette-default-surface-3);
}

/* Show/hide elements based on screen size for mobile and desktop views */
@container (max-width: 1003px) {
  .layout-mixed .v-mobile-container-hide {
    display: none;
  }

  .layout-mixed .v-desktop-container-hide {
    display: block;
  }

  .layout-mixed .v-desktop-container-hide.v-hide {
    display: none;
  }
}

@container (min-width: 1004px) {
  .layout-mixed .v-mobile-container-hide {
    display: flex;
  }

  .layout-mixed .v-desktop-container-hide {
    display: none;
  }
}

