import { Button, Typography } from '@visa/nova-react';
import cn from 'clsx';
import { Highlight, themes } from 'prism-react-renderer';
import { useState } from 'react';
import Styles from './chat-code-block-css.module.scss';
import { VisaCheckmarkTiny, VisaCopyTiny } from '@visa/nova-icons-react';

/**
 * Props for the ChatCodeBlock component
 *
 * @property className - (optional) Additional CSS class names
 * @property code - (optional) Code string to display
 * @property deprecated - (optional) Applies strikethrough styling
 * @property exampleName - (optional) Name used in aria-label
 * @property language - (optional) Programming language for syntax highlighting
 */
type CodeProperties = {
  className?: string;
  code?: string;
  deprecated?: boolean;
  exampleName?: string;
  language?: string;
};

/**
 * Syntax-highlighted code block with copy-to-clipboard functionality and line numbers.
 * Uses prism-react-renderer with GitHub theme for highlighting and shows visual feedback when code is copied.
 */
const ChatCodeBlock = ({
  className = '',
  code = '',
  deprecated,
  exampleName = '',
  language = 'typescript',
  ...remainingProps
}: CodeProperties) => {
  const formattedCode = code.trim();
  const [copied, setCopied] = useState(false);

  // Copy code to clipboard with visual feedback
  const copyToClipboard = (text: string) => {
    if (!copied) {
      navigator.clipboard.writeText(text);
      setCopied(true);
      // Reset after 2 seconds
      window.setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <Highlight code={formattedCode} language={language} theme={themes.github} {...remainingProps}>
      {({ style, tokens, getLineProps, getTokenProps }) => (
        <div className={Styles.codeContainer}>
          {/* Copy button with success feedback */}
          <div className={Styles.copyButtonContainer}>
            <Button
              aria-label={`Copy code snippet of ${exampleName}`}
              buttonSize="small"
              className={cn(Styles.copyButton, copied && Styles.copied)}
              colorScheme="tertiary"
              iconButton
              onClick={() => copyToClipboard(formattedCode)}
            >
              {copied ? <VisaCheckmarkTiny /> : <VisaCopyTiny />}
              <Typography tag="span" variant="label-active">
                Copied!
              </Typography>
            </Button>
          </div>
          {/* Scrollable code container with line numbers */}
          <div className={cn(Styles.overflowContainer)}>
            <pre
              className={cn(Styles.codeSnippet, className)}
              style={{ ...style, textDecoration: deprecated ? 'line-through' : 'inherit' }}
            >
              {tokens.map((line, i) => (
                <span {...getLineProps({ key: i, line })} key={i}>
                  {/* Line number column */}
                  <span
                    style={{
                      display: 'inline-block',
                      opacity: '0.3',
                      userSelect: 'none',
                      width: '2em',
                    }}
                  >
                    {i + 1}
                  </span>
                  {line.map((token, key) => (
                    <span {...getTokenProps({ key, token })} key={key} />
                  ))}
                </span>
              ))}
            </pre>
          </div>
        </div>
      )}
    </Highlight>
  );
};

export default ChatCodeBlock;

