import { VisaErrorTiny, VisaInformationTiny, VisaSuccessTiny, VisaWarningTiny } from '@visa/nova-icons-react';
import type { BadgeProperties } from '@visa/nova-react';

/**
 * Row data to store string values for each column.
 * ie. { 'Status': 'Approved', 'Amount': '$1000', ... }
 */
export type RowData = Record<string, string>;

/**
 * Row data for multi-action tables, where values can be string or an array of action buttons.
 */
export type RowDataMultiActions = Record<string, string | ActionButtons[]>;

/**
 * Column data type definition.
 *
 * @property badge - (optional) Whether the column displays badge components
 * @property compact - (optional) Whether the column should use compact spacing
 * @property genericHeaderActions - (optional) Whether the column has generic header actions
 * @property headerActions - (optional) Settings for filter options
 * @property headerActions.options - Available filter options (FilterOption array or string array)
 * @property headerActions.selectedOptions - Currently selected filter values
 * @property hidden - (optional) Whether the column is currently hidden
 * @property identifier - (optional) Whether this column serves as the row identifier
 * @property name - Display name of the column
 * @property render - (optional) Custom function to render cell content
 * @property renderActionButtons - (optional) Custom function to render action buttons in cells
 * @property sortable - Whether the column supports sorting
 */
export type ColData = {
  badge?: boolean;
  compact?: boolean;
  genericHeaderActions?: boolean;
  headerActions?: {
    options: FilterOption[] | string[];
    selectedOptions: string[];
  };
  hidden?: boolean;
  identifier?: boolean;
  name: string;
  render?: (rowData: RowData, colID?: string) => React.ReactNode;
  renderActionButtons?: (rowData: RowDataMultiActions, colID?: string) => React.ReactNode;
  sortable: boolean;
};

/**
 * Sort key type definition.
 *
 * @property column - Name of the column to sort by
 * @property direction - Sort direction (ascending, descending, or none)
 */
export type SortKeyType = {
  column: string;
  direction: SortType;
};

/**
 * Filterable table state type definition.
 *
 * @property column - Name of the column currently sorted
 * @property direction - Current sort direction (ascending, descending, or none)
 * @property filters - Currently applied filters grouped by column name
 *
 * Same as SortKeyType but with filters
 */
export type FilterableTableState = {
  column: string;
  direction: SortType;
  filters: Record<string, string[]>;
};

/**
 * Sort type constants.
 */
export const SortType = {
  NONE: 'none',
  ASC: 'ascending',
  DESC: 'descending',
} as const;
export type SortType = (typeof SortType)[keyof typeof SortType];

/**
 * Action buttons available in the dynamic table.
 */
export const ActionButtons = {
  EDIT: 'edit',
  DELETE: 'delete',
} as const;
export type ActionButtons = (typeof ActionButtons)[keyof typeof ActionButtons];

/**
 * Badge configurations for different statuses.
 *
 * @property type - Badge type from Nova (critical, neutral, stable, subtle, warning)
 * @property icon - Icon element to display in the badge
 * @property text - Display text for the badge status
 */
export const badgeConfigs: Array<{
  type: BadgeProperties['badgeType'];
  icon: React.ReactNode;
  text: string;
}> = [
  {
    type: 'critical',
    icon: <VisaErrorTiny aria-label="error" />,
    text: 'Declined',
  },
  {
    type: 'neutral',
    icon: <VisaInformationTiny aria-label="information" />,
    text: 'In progress',
  },
  {
    type: 'stable',
    icon: <VisaSuccessTiny aria-label="success" />,
    text: 'Approved',
  },
  {
    type: 'warning',
    icon: <VisaWarningTiny aria-label="warning" />,
    text: 'On hold',
  },
];

/**
 * Represents a single filter option with label and checked status.
 *
 * @property label - Display text for the filter option
 * @property checked - (optional) Whether the filter option is currently selected
 */
export type FilterOption = { label: string; checked?: boolean };

/**
 * A group of filter options organized by filter name.
 */
export type FilterOptions = Record<string, FilterOption[]>;

.v-table {
  thead {
    .v-th {
      // column header buttons should be extra small and less rounded
      // this abides by the minimum size guidelines from WCAG for web
      .v-button-icon {
        --v-button-default-block-size: var(--size-scalable-26);
        --v-button-default-border-radius: var(--size-rounded-small);
      }
    }
  }

  /** Apply to columns that should be as compact in width as possible */
  .compact-column {
    &.v-th {
      /** This is a trick to make the column as small as possible.
          Setting min-content or fit-content does not work. */
      inline-size: 1%;
    }

    &.v-td {
      inline-size: 1%;
      --v-table-data-padding-inline: var(--size-scalable-6);
    }

    &.v-td {
      /** Center content in compact columns */
      text-align: center;
    }
  }

  /** Allow button actions to be inline, even when in compact column */
  .actions-wrapper {
    display: inline-flex;
    gap: 0.5rem;
    inline-size: max-content;
  }

  &.fixed-table {
    .sticky-row {
      position: sticky;
      top: 0;
      z-index: 1;

      // Drop shadow for sticky row
      &::after {
        content: '';
        top: 0;
        left: 0;
        box-shadow: var(--elevation-large);
        block-size: 100%;
        inline-size: 100%;
        position: absolute;
        pointer-events: none; // allow clicks to pass through
      }

      .v-th,
      .v-td {
        // border-inline: 0 removes extra spacing caused by border-collapse: separate
        border-inline: 0;
        z-index: 2;
      }
    }

    &:has(.sticky-row) {
      // to keep the border between header and body when scrolling,
      // border-collapse must be separate
      --v-table-border-collapse: separate;
    }

    .pinned-column {
      --v-table-header-bg-color: var(--palette-default-surface-3);
      inset-inline-start: 0;
      position: sticky;
      z-index: 1;

      /** Drop shadow for pinned column */
      &::before {
        content: '';
        top: 0;
        left: 0;
        box-shadow: var(--elevation-medium);
        block-size: 100%;
        inline-size: 100%;
        position: absolute;
      }

      &.v-td {
        border: 0;
      }
    }

    // maintain alternating row colors when pinned column is present
    &.v-table-alt:has(.pinned-column) {
      tr:nth-child(odd) td {
        background-color: var(--v-table-background);
      }
      tr:nth-child(even) td {
        background-color: var(--v-table-background-alt);
      }
    }

    .v-th:has(.v-button.v-dropdown[aria-expanded='true']) {
      // when a dropdown is open in the header, make sure it is above the shadow
      z-index: 2;
    }
  }

  &.accordion-style-table {
    /**
    * Override accordion display styles to work with table elements
    * The directive names and class names don't always align,
    * so we're using the directive selectors for clarity
    **/
    &.v-accordion {
      display: table;
    }

    tbody {
      display: table-row-group;

      tr.v-accordion-heading {
        display: table-row;
        border: 0;

        td {
          // add a border to the start of each accordion header row
          border-block-start: var(--v-accordion-panel-border-size) var(--v-accordion-panel-border-style)
            var(--v-accordion-panel-border-color);
        }

        // for an open accordion item, add a border to bottom of row
        &:has(.v-button[aria-expanded='true']) {
          td {
            border-block-end: var(--v-accordion-panel-border-size) var(--v-accordion-panel-border-style)
              var(--v-accordion-panel-border-color);
          }
        }
      }

      &:first-of-type {
        tr.v-accordion-heading td {
          // remove border of first accordion header row
          border-block-start: 0;
        }
      }
    }

    td.v-accordion-panel {
      border: 0;
    }
  }

  // selected row (row with checked checkbox)
  tr:has(.row-selection-checkbox:checked) {
    .v-td {
      border-color: var(--palette-default-surface-lowlight);
      background-color: var(--palette-default-surface-lowlight);
      position: relative;

      // blue highlight/indicator on inline-start of row
      &:first-of-type {
        &::before {
          content: '';
          /** push it up 1 border width, and make sure the height is 100% + 2 border widths (--size-scalable-1) */
          block-size: calc(100% + 2 * var(--size-scalable-1));
          inset-block-start: calc(-1 * var(--size-scalable-1));
          position: absolute;
          inset-block-start: 0;
          inset-inline-start: 0;
          border: 3px solid var(--palette-default-active);
        }
      }
    }

    &:last-of-type {
      .v-td {
        &:first-of-type {
          &::before {
            // On the last row, subtract 2px from the height to account for border radius.
            // This prevents the extra height from causing a scrollbar to appear on the table.
            block-size: calc(100% + (2 * var(--size-scalable-1)) - 2px);
          }
        }
      }
    }
  }
}

.v-accordion-heading {
  &.v-button {
    /** Make badges position correctly inside header buttons instead of as a notification badge */
    .v-badge-number {
      position: relative;
      justify-content: center;
    }
  }
}

.v-action-bar {
  // remove rounded corners for action bars in dynamic table examples
  --v-surface-border-radius: var(--size-rounded-none);

  .v-dropdown-menu.v-surface {
    /**
    * Reset background for dropdown menus in action bars.
    * Some action bars may have a different surface background color
    * that the dropdowns would otherwise inherit.
    */
    --v-surface-background: var(--palette-default-surface-1);
  }
}

import type { BadgeProperties } from '@visa/nova-react';
import { badgeConfigs, SortType, type ColData, type RowData, type SortKeyType } from './dynamic-table.constants';

/**
 * Sorts the data based on the given column and updates the sort state.
 *
 * @param sortKey - The key and direction to sort by
 * @param currentColumnData - Current column definitions
 * @param currentSortedData - Current data to be sorted
 * @returns Sorted data
 */
export const revisedSortTableData = (
  sortKey: SortKeyType,
  currentColumnData: ColData[] | ColData[],
  currentSortedData: RowData[]
): RowData[] => {
  const columnName = sortKey.column;
  // Create a copy of the column data to avoid mutating the original
  const columnDataCopy = currentColumnData.map(col => ({ ...col }));

  const columnToSort = columnDataCopy.find(c => c.name === columnName);
  if (!columnToSort || !columnToSort.sortable) return currentSortedData;

  // Create a copy of the data before sorting to avoid mutating the original array
  const preSortedData = [...currentSortedData].sort((item1, item2) => {
    const a = item1[columnName];
    const b = item2[columnName];
    if (columnToSort.badge) {
      const aType = badgeConfigs.find(badge => badge.text === a)?.type;
      const bType = badgeConfigs.find(badge => badge.text === b)?.type;
      /** badge sorting */
      return sortBadgeItems(aType, bType);
    } else if (typeof a === 'string' && typeof b === 'string') {
      /** string sorting */
      return sortStringItems(a, b);
    } else if (typeof a === 'boolean' && typeof b === 'boolean') {
      /** boolean sorting */
      return sortBoolItems(a, b);
    }
    return 0;
  });

  // return sorted data using new direction
  if (sortKey.direction === SortType.ASC) {
    return preSortedData;
  } else {
    const reversedData = [...preSortedData].reverse();
    return reversedData;
  }
};

/**
 * Sorts boolean items.
 *
 * @param a - First boolean value
 * @param b - Second boolean value
 * @returns Sorting order
 */
export const sortBoolItems = (a: boolean, b: boolean): number => {
  if (a < b) {
    return -1;
  } else if (a > b) {
    return 1;
  }
  return 0;
};

/**
 * Sorts string items.
 *
 * @param a - First string value
 * @param b - Second string value
 * @returns Sorting order
 */
export const sortStringItems = (a: string, b: string): number => {
  // START GENAI@CHATGPT5
  return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
  // END GENAI@CHATGPT5
};

/**
 * Sorts badge items by critical to least critical.
 *
 * @param a - Badge type of first item
 * @param b - Badge type of second item
 * @returns Sorting order
 */
export const sortBadgeItems = (a: BadgeProperties['badgeType'], b: BadgeProperties['badgeType']): number => {
  const badgeOrder: BadgeProperties['badgeType'][] = ['critical', 'warning', 'stable', 'neutral'];
  const indexA = badgeOrder.indexOf(a);
  const indexB = badgeOrder.indexOf(b);

  if (indexA < indexB) {
    return -1;
  } else if (indexA > indexB) {
    return 1;
  }
  return 0;
};

