import {
  MessageIcon,
  VisaArrowBackTiny,
  VisaArrowForwardTiny,
  VisaCheckmarkTiny,
  VisaChevronRightTiny,
  VisaCloseTiny,
  VisaErrorAltTiny,
  VisaErrorTiny,
} from '@visa/nova-icons-react';
import {
  Badge,
  Button,
  ContentCard,
  Input,
  InputContainer,
  InputMessage,
  Label,
  SectionMessage,
  SectionMessageCloseButton,
  SectionMessageContent,
  Typography,
  Utility,
  UtilityFragment,
  Wizard,
  WizardStep,
  useFocusTrap,
  useWizard,
} from '@visa/nova-react';
import { useEffect, useRef, useState, type CSSProperties, type ChangeEvent, type RefObject } from 'react';
import { SaveFlag } from './shared/save-flag';
import { SuccessMessage } from './shared/success-message';
import { SummaryPage } from './shared/summary-page';
import { ExitDialog } from './shared/exit-dialog';

// Unique ID for wizard elements. Customize this or use React.useId() for dynamic generation.
const id = 'responsive-horizontal-wizard';
const navRegionAriaLabel = 'Responsive horizontal wizard';

/**
 * Step configuration defining wizard structure.
 * Each step requires: label (badge text), title, inputLabel, inputId, and buttonId.
 * The final step (without inputId) is reserved for the summary page.
 */
const steps = [
  {
    label: '1',
    title: 'Step 1 label',
    inputLabel: 'Label',
    inputId: `${id}-step-1-input`,
    buttonId: `${id}-step-1-button`,
  },
  {
    label: '2',
    title: 'Step 2 label',
    inputLabel: 'Label',
    inputId: `${id}-step-2-input`,
    buttonId: `${id}-step-2-button`,
  },
  {
    label: '3',
    title: 'Step 3 label',
    inputLabel: 'Label',
    inputId: `${id}-step-3-input`,
    buttonId: `${id}-step-3-button`,
  },
  {
    label: '4',
    title: 'Step 4 label',
    inputLabel: 'Label',
    inputId: `${id}-step-4-input`,
    buttonId: `${id}-step-4-button`,
  },
  {
    label: '5',
    title: 'Step 5 label',
  },
];

const exitDialogId = `${id}-exit-warning-dialog`;

const DEFAULT_INPUT_VALUES = Array(steps.length).fill('');

/**
 * Multi-step form with responsive horizontal layout, validation, auto-save, and summary review.
 */
export const ResponsiveHorizontalWizard = () => {
  const {
    currentStep,
    isStepAvailable,
    isLastStep,
    isStepComplete,
    isStepError,
    onStepError,
    onStepChange,
    onStepComplete,
    onStepPrevious,
    onWizardReset,
  } = useWizard({ length: steps.length });

  // Tracks step changes to trigger focus management in useEffect
  const [hasWizardStepChanged, setHasWizardStepChanged] = useState(false);

  const { onKeyNavigation, ref: exitDialogRef } = useFocusTrap();

  const [inputValues, setInputValues] = useState(DEFAULT_INPUT_VALUES);

  const [showSavedFlag, setShowSavedFlag] = useState(false);
  const [formSubmitted, setFormSubmitted] = useState(false);
  const [visibleErrorMessages, setVisibleErrorMessages] = useState<boolean[]>(Array(steps.length).fill(true));

  // Ref maps for programmatic focus management when navigating or encountering errors
  const inputRefs = useRef(new Map());
  function getInputRefMap() {
    if (!inputRefs.current) {
      inputRefs.current = new Map();
    }
    return inputRefs.current;
  }

  const buttonRefs = useRef(new Map());
  function getButtonRefMap() {
    if (!buttonRefs.current) {
      buttonRefs.current = new Map();
    }
    return buttonRefs.current;
  }

  const editButtonRefs = useRef<(HTMLButtonElement | null)[]>([]);

  // Manages focus after step changes for improved keyboard navigation
  useEffect(() => {
    if (!hasWizardStepChanged) {
      return;
    }
    // apply focus to the input field of the current step
    const inputRefsMap = getInputRefMap();
    const currentStepInputNode = inputRefsMap.get(steps[currentStep].inputId);
    if (currentStepInputNode) {
      currentStepInputNode.focus();
    } else {
      // focus the first available edit button in the array
      const firstEditButton = editButtonRefs.current.find(ref => ref !== null);
      if (firstEditButton) {
        firstEditButton.focus();
      }
    }

    setHasWizardStepChanged(false);
  }, [hasWizardStepChanged, currentStep]);

  /**
   * Updates form data for a specific step.
   *
   * @param index - Step index to update
   * @param event - Input change event containing new value
   */
  const handleInputChange = (index: number, event: ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value;
    const newInputValues = [...inputValues];
    newInputValues[index] = value;
    setInputValues(newInputValues);
  };

  /**
   * Validates current step and advances to next.
   * Shows error if validation fails.
   */
  const handleClickNext = () => {
    if (!inputValues[currentStep]) {
      onStepError(currentStep);
      // Reset error message visibility for this step
      const newVisibleErrorMessages = [...visibleErrorMessages];
      newVisibleErrorMessages[currentStep] = true;
      setVisibleErrorMessages(newVisibleErrorMessages);
      // find the input element with the error in the refs map and set focus on it
      const inputRefsMap = getInputRefMap();
      const currentStepInputNode = inputRefsMap.get(steps[currentStep].inputId);
      currentStepInputNode.focus();
      return;
    }

    setHasWizardStepChanged(true);
    setShowSavedFlag(false);
    onStepComplete(currentStep);
  };

  /**
   * Returns to previous step without validation.
   */
  const handleClickPrevious = () => {
    setHasWizardStepChanged(true);
    setShowSavedFlag(false);
    onStepPrevious();
  };

  /**
   * Displays save confirmation flag.
   */
  const handleSave = () => {
    setShowSavedFlag(true);
  };

  /**
   * Resets wizard to initial state.
   */
  const handleResetWizard = () => {
    setHasWizardStepChanged(true);
    setInputValues(DEFAULT_INPUT_VALUES);
    setFormSubmitted(false);
    onWizardReset();
  };

  /**
   * Collects form data and marks wizard as submitted.
   */
  const handleSubmit = () => {
    const formValues: { [key: string]: string } = {};
    steps.forEach((step, i) => {
      if (!step.inputId) return;
      formValues[step.inputId] = inputValues[i];
    });
    setFormSubmitted(true);
  };

  /**
   * Opens exit confirmation dialog.
   */
  const handleExit = () => {
    exitDialogRef.current?.showModal();
  };

  /**
   * Hides error section message for a specific step.
   *
   * @param stepIndex - Index of the step whose error message should be hidden
   */
  const handleErrorMessageClose = (stepIndex: number) => {
    const newVisibleErrorMessages = [...visibleErrorMessages];
    newVisibleErrorMessages[stepIndex] = false;
    setVisibleErrorMessages(newVisibleErrorMessages);
  };

  /**
   * Handles direct navigation to a step from the wizard nav or summary page.
   * Validates current step when navigating forward.
   *
   * @param i - Target step index
   */
  const handleClickStep = (i: number) => {
    setHasWizardStepChanged(true);

    // If navigating forward, validate current step like "Next"
    if (i > currentStep) {
      if (!inputValues[currentStep]) {
        onStepError(currentStep);
        const newVisibleErrorMessages = [...visibleErrorMessages];
        newVisibleErrorMessages[currentStep] = true;
        setVisibleErrorMessages(newVisibleErrorMessages);
        // focus input with error
        const inputRefsMap = getInputRefMap();
        const currentStepInputNode = inputRefsMap.get(steps[currentStep].inputId);
        if (currentStepInputNode) {
          currentStepInputNode.focus();
        }
        return;
      }
      onStepComplete(currentStep);
      onStepChange(i);
    } else {
      onStepChange(i);
    }
  };

  /**
   * Renders the final summary page with review and edit capabilities.
   */
  const renderSummaryStep = () => (
    <SummaryPage
      steps={steps}
      inputValues={inputValues}
      onStepClick={handleClickStep}
      renderActionButtons={renderActionButtons}
      maxWidth="603px"
      editButtonRefs={editButtonRefs.current}
    />
  );

  /**
   * Renders wizard action buttons with responsive layouts.
   * Desktop: Horizontal layout with buttons grouped left/right.
   * Mobile: Vertical stacked layout with full-width buttons.
   */
  const renderActionButtons = () => {
    return (
      <>
        <Utility vContainerHide="xs" vMarginTop={40}>
          <Utility vJustifyContent="between" vFlex vFlexWrap vGap={24}>
            <Utility vJustifyContent="start" vFlex vFlexWrap vColGap={24} vRowGap={16}>
              <Button onClick={handleSave} colorScheme="secondary">
                Save
              </Button>
              <Button onClick={handleExit} colorScheme="tertiary">
                Exit
              </Button>
            </Utility>
            <Utility vJustifyContent="end" vFlex vFlexWrap vGap={24}>
              <UtilityFragment vHide={currentStep === 0}>
                <Button onClick={handleClickPrevious} colorScheme="secondary">
                  <VisaArrowBackTiny />
                  Back
                </Button>
              </UtilityFragment>
              <UtilityFragment vHide={currentStep === steps.length - 1}>
                <Button onClick={handleClickNext}>
                  Next
                  <VisaArrowForwardTiny />
                </Button>
              </UtilityFragment>
              <UtilityFragment vHide={currentStep !== steps.length - 1}>
                <Button onClick={handleSubmit}>Submit</Button>
              </UtilityFragment>
            </Utility>
          </Utility>
        </Utility>
        <UtilityFragment vContainerHide="desktop">
          <Utility vFlex vFlexCol vGap={16} vContainerHide="sm" vMarginTop={40}>
            <Button onClick={handleSave} colorScheme="secondary">
              Save
            </Button>
            <Button onClick={handleExit} colorScheme="tertiary">
              Exit
            </Button>
            <UtilityFragment vHide={currentStep === 0}>
              <Button onClick={handleClickPrevious} colorScheme="secondary">
                <VisaArrowBackTiny />
                Back
              </Button>
            </UtilityFragment>
            <UtilityFragment vHide={currentStep === steps.length - 1}>
              <Button onClick={handleClickNext}>
                Next
                <VisaArrowForwardTiny />
              </Button>
            </UtilityFragment>
            <UtilityFragment vHide={currentStep !== steps.length - 1}>
              <Button onClick={handleSubmit}>Submit</Button>
            </UtilityFragment>
          </Utility>
        </UtilityFragment>
      </>
    );
  };

  if (formSubmitted) {
    return <SuccessMessage onReset={handleResetWizard} />;
  }

  /**
   * Renders full horizontal wizard with step labels and titles for larger screens.
   */
  const renderDesktopWizard = () => {
    return (
      <nav aria-label={`${navRegionAriaLabel}-desktop`} style={{ inlineSize: '100%' }}>
        <UtilityFragment vJustifyContent="center">
          <Wizard>
            {steps.map((step, i) => (
              <WizardStep key={`horizontal-wizard-step-${i + 1}`} aria-current={currentStep === i ? 'step' : undefined}>
                {isStepAvailable(i) ? (
                  <>
                    <Button
                      className={`${
                        currentStep === i
                          ? 'v-typography-label-large-active v-typography-color-default'
                          : 'v-typography-label-large'
                      }`}
                      colorScheme="tertiary"
                      aria-label={`${isStepError(i) ? 'Error ' : isStepComplete(i) ? 'Completed ' : `${i + 1} `}${
                        step.title
                      }`}
                      onClick={() => handleClickStep(i)}
                      id={step.buttonId}
                      ref={node => {
                        const map = getButtonRefMap();
                        if (node) {
                          // store the node in the inputRefs Map
                          map.set(step.buttonId, node);
                        } else {
                          map.delete(step.buttonId);
                        }
                      }}
                    >
                      <Utility vFlex vGap={8}>
                        <Badge
                          aria-current={i === currentStep ? 'step' : undefined}
                          active={i === currentStep && !isStepError(i) && !isStepComplete(i)}
                          badgeType={isStepError(i) ? 'critical' : isStepComplete(i) ? 'stable' : 'subtle'}
                          badgeVariant="icon"
                          clear={i !== currentStep}
                          tag="span"
                        >
                          {isStepError(i) ? (
                            <VisaErrorAltTiny />
                          ) : isStepComplete(i) ? (
                            <VisaCheckmarkTiny />
                          ) : (
                            step.label
                          )}
                        </Badge>
                        <Typography tag="span">{step.title}</Typography>
                      </Utility>
                      {i < steps.length - 1 && <VisaChevronRightTiny className="v-typography-color-subtle" />}
                    </Button>
                  </>
                ) : (
                  <>
                    <Utility vFlex vGap={8}>
                      <Badge
                        active={i === currentStep && !isStepError(i) && !isStepComplete(i)}
                        clear={i !== currentStep}
                        badgeType={isStepError(i) ? 'critical' : isStepComplete(i) ? 'stable' : 'subtle'}
                        badgeVariant="icon"
                        tag="span"
                      >
                        {isStepError(i) ? <VisaErrorAltTiny /> : isStepComplete(i) ? <VisaCheckmarkTiny /> : step.label}
                      </Badge>
                      <Typography variant={i === currentStep ? 'label-large-active' : 'label-large'}>
                        {step.title}
                      </Typography>
                    </Utility>
                    {!isLastStep(i) && <VisaChevronRightTiny className="v-typography-color-subtle" />}
                  </>
                )}
              </WizardStep>
            ))}
          </Wizard>
        </UtilityFragment>
      </nav>
    );
  };

  /**
   * Renders compact wizard showing only badge indicators for smaller screens.
   */
  const renderMobileWizard = () => {
    return (
      <nav aria-label={`${navRegionAriaLabel}-mobile`} style={{ inlineSize: '100%' }}>
        <UtilityFragment vJustifyContent="center">
          <Wizard compact>
            {steps.map((step, i) => (
              <WizardStep key={`horizontal-wizard-step-${i + 1}`} aria-current={currentStep === i ? 'step' : undefined}>
                <Badge
                  aria-current={i === currentStep ? 'step' : undefined}
                  active={i === currentStep && !isStepError(i) && !isStepComplete(i)}
                  badgeType={isStepError(i) ? 'critical' : isStepComplete(i) ? 'stable' : 'subtle'}
                  badgeVariant="icon"
                  clear={i !== currentStep}
                  tag="span"
                >
                  {isStepError(i) ? <VisaErrorAltTiny /> : isStepComplete(i) ? <VisaCheckmarkTiny /> : step.label}
                </Badge>
              </WizardStep>
            ))}
          </Wizard>
        </UtilityFragment>
      </nav>
    );
  };

  return (
    <Utility vFlex vFlexCol vGap={40} vAlignItems="center" style={{ containerType: 'inline-size' } as CSSProperties}>
      <SaveFlag show={showSavedFlag} onClose={() => setShowSavedFlag(false)} />
      <UtilityFragment vContainerHide="mobile">{renderDesktopWizard()}</UtilityFragment>
      <UtilityFragment vContainerHide="desktop">{renderMobileWizard()}</UtilityFragment>
      <Utility style={{ maxInlineSize: '603px', inlineSize: '100%' }}>
        {steps.slice(0, steps.length - 1).map((step, i) => {
          return (
            <Utility key={i} vHide={currentStep !== i}>
              <UtilityFragment vFlex vFlexCol vGap={24} vPadding={48}>
                <ContentCard style={{ boxShadow: 'none' }}>
                  <Utility vFlex vFlexCol vGap={isStepError(i) ? 16 : 8}>
                    <Typography variant="headline-2">{step.title}</Typography>
                    {isStepError(i) && visibleErrorMessages[i] && (
                      <SectionMessage messageType="error" id="step-error-compact">
                        <MessageIcon messageType="error" />
                        <UtilityFragment vPaddingLeft={2} vPaddingBottom={2}>
                          <SectionMessageContent>
                            <Typography>
                              One or more required fields are missing. Complete all required fields to continue.
                            </Typography>
                          </SectionMessageContent>
                        </UtilityFragment>
                        <SectionMessageCloseButton onClick={() => handleErrorMessageClose(i)}>
                          <VisaCloseTiny />
                        </SectionMessageCloseButton>
                      </SectionMessage>
                    )}
                    <Typography variant="body-1">* Indicates a required field.</Typography>
                  </Utility>
                  <Utility vFlex vFlexCol vGap={4}>
                    <Label htmlFor={step.inputId}>{`* ${step.inputLabel}`}</Label>
                    <InputContainer>
                      <Input
                        aria-describedby={isStepError(i) ? `step-error-compact ${step.inputId}-message` : undefined}
                        aria-required="true"
                        aria-invalid={isStepError(i)}
                        id={step.inputId}
                        type="text"
                        value={inputValues[i]}
                        onChange={e => handleInputChange(i, e as ChangeEvent<HTMLInputElement>)}
                        ref={node => {
                          const map = getInputRefMap();
                          if (node) {
                            // store the node in the inputRefs Map
                            map.set(step.inputId, node);
                          } else {
                            map.delete(step.inputId);
                          }
                        }}
                      />
                    </InputContainer>
                    {isStepError(i) && (
                      <InputMessage id={`${step.inputId}-message`}>
                        <VisaErrorTiny />
                        This is a required field.
                      </InputMessage>
                    )}
                  </Utility>
                </ContentCard>
              </UtilityFragment>
              <UtilityFragment vMarginTop={10}>
                <Typography variant="body-3">Changes have been automatically saved.</Typography>
              </UtilityFragment>
              {renderActionButtons()}
            </Utility>
          );
        })}
        {currentStep === steps.length - 1 && renderSummaryStep()}
      </Utility>
      <ExitDialog
        exitDialogId={exitDialogId}
        exitDialogRef={exitDialogRef as RefObject<HTMLDialogElement>}
        onKeyNavigation={onKeyNavigation}
      />
    </Utility>
  );
};

