export const PaddingLeftSpacing = () => {
  return (
    <Utility vFlex>
      <Utility
        vPaddingLeft={20}
        style={
          {
            background: 'var(--palette-default-surface-highlight)',
            border: '1px dashed var(--palette-default-active-subtle)',
          } as CSSProperties
        }
      >
        <Utility vPadding={16} element={<Surface />} vPaddingBottom={20}>
          Content Area
        </Utility>
      </Utility>
    </Utility>
  );
};

